package dev.redstoneengineering.block;import com.mojang.serialization.MapCodec;import dev.redstoneengineering.*;import dev.redstoneengineering.physics.*;import net.minecraft.core.*;import net.minecraft.network.chat.Component;import net.minecraft.server.level.ServerLevel;import net.minecraft.util.RandomSource;import net.minecraft.world.*;import net.minecraft.world.entity.player.Player;import net.minecraft.world.level.*;import net.minecraft.world.level.block.Block;import net.minecraft.world.level.block.state.BlockState;import net.minecraft.world.phys.BlockHitResult;public class SoulSandReservoirBlock extends Block{public SoulSandReservoirBlock(Properties p){super(p);}@Override public MapCodec<SoulSandReservoirBlock> codec(){return RedstoneEngineering.SOUL_SAND_RESERVOIR_CODEC.value();}@Override protected void onPlace(BlockState s,Level l,BlockPos p,BlockState o,boolean m){super.onPlace(s,l,p,o,m);if(l instanceof ServerLevel sl)sl.scheduleTick(p,this,40);}@Override protected void tick(BlockState s,ServerLevel l,BlockPos p,RandomSource r){SoulFluxNetwork.decay(l,p);l.scheduleTick(p,this,40);}@Override protected InteractionResult useWithoutItem(BlockState s,Level l,BlockPos p,Player pl,BlockHitResult h){if(!l.isClientSide)pl.displayClientMessage(Component.literal("Soul reservoir Qs="+SoulFluxNetwork.charge(l,p)+"/100 | slow persistent state"),true);return InteractionResult.sidedSuccess(l.isClientSide);}}